head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isurCd = "";          // 발행기관코드 (원본 Isur_cd — arr[0])
scwin.isurNm = "";          // 발행기관명·종목명 (원본 Isur_nm — arr[1], 형제 팝업 전환 때 그대로 넘긴다)
scwin.secugrpId = "";       // 증권그룹ID (원본 Secugrp_id — arr[2], ETN 은 EN)
scwin.mktId = "";           // 시장구분코드 (원본 Mkt_id — arr[3])
scwin.bzProcsNo = "";       // 업무처리번호 — 비어 있으면 신규, 있으면 수정 (원본 fr_bz_procs_no — arr[4])
scwin.tpCd = "";            // 관리종목지정업무구분코드 (원본 tpCd — arr[5], 이 화면은 1: 사유변경)
scwin.isuCd = "";           // 종목코드 (원본 Isu_cd — arr[6])
scwin.selTp = "";           // 선택 구분 0: 형제 팝업에서 옴, 1: 종목, 2: 발행회사, 3: 전체 (원본 gubun — arr[7])
scwin.orgBzProcsNo = "";    // 원 지정 건 업무처리번호 (원본 fr_org_bz_procs_no — arr[8])
scwin.trJob = "";           // 처리구분 I: 저장, U: 수정, D: 삭제 (원본 trsIdx)
scwin.curDate = "";         // 서버 현재일 (yyyyMMdd)
scwin.isSaved = false;      // 저장·수정에 성공했는지 — 닫을 때 부모에 돌려준다
scwin.BZ_TP_RSN_CHG = "1";      // 관리종목지정업무구분코드 1: 사유변경
scwin.BZ_TP_RELEAS = "4";       // 관리종목지정업무구분코드 4: 해제
scwin.RSNCD_ADM_DESIGN = "2";   // 사유 찾기 구분 — 관리종목지정사유 (pcc list_common RSNCD_ADM_DESIGN)
scwin.DEFAULT_GRND_REGUL = "유가증권시장상장규정 제149조의6제1항";   // 신규 근거규정 기본값 (원본 dts_Mst OnLoadCompleted)
scwin.DSCL_FORM_CD = "68346";   // 공시안내문 서식코드 (원본 arr[0])
scwin.DSCL_MKT_ID = "1";        // 공시안내문 시장구분 (원본 arr[3])
// 원본 : /etn/ULDSTF08034.gfm (ETN 관리종목지정 사유변경 팝업)
/*
 * 화면 동작 — (팝업)ETN 관리종목지정 사유변경
 *  - 부모 ULDSTF08031(관리종목지정 목록)이 openPopup 의 data 로 연다. 업무처리번호가 없으면 신규, 있으면 수정이다.
 *    지정(08032·08032_new)·사유변경(08034) 팝업의 [사유변경]으로도 열린다 — 이때도 부모 08031 이 연다(selTp "0").
 *  - 위 표는 원 지정 건(조회 전용), 아래 표가 이번 사유변경 입력이다. 변경 전 사유는 신규면 최신 지정 건의 사유를 불러온다.
 *  - [해제]·[사유변경] 은 이 창을 닫으며 다음에 열 화면을 돌려준다(closePopup 의 next) — 부모가 재조회 뒤 그 화면을 연다.
 *  - 공시안내문작성(ULDSTF92024, 서식 68346). 닫힌 뒤 반환 { isSaved } 또는 X 닫기면 부모가 목록을 다시 조회한다.
 * 통신·데이터 정의 : 7화면 공용 명세 ui/completed/ULDSTF08031/ULDSTF08031,…,ULDSTF08037_API.md 의 이 화면 블록(1·4·6·7·10·13·14)
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF08034/ULDSTF08034.md (§번호는 이 문서의 절)
 */

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
// [해제]·[사유변경] 은 원본도 buttonSet 밖에서 따로 켜고 껐다(scwin.setRelAndChgRsnBtnShow).
scwin.BTN_MAP = {
    save : "btn_Save",          // [저장]
    modify : "btn_Update",      // [수정]
    "delete" : "btn_Delete",    // [삭제]
    guide : "btn_Dscl"          // [안내문작성]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08034.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 초기화. 버튼을 잠그고 달력 검사를 건 뒤, 부모 파라미터로 신규·수정을 가른다. (원본 gform onload — §3)
 *
 * 부모는 openPopup 의 3번째 인자를 평면으로 넘기므로 $c.data.getParameter() 로 전체를 받아 키를 바로 읽는다(공통 계약서 §3.1).
 * 로딩 중에는 버튼을 전부 잠근다 — 조회가 실패해도 버튼이 XML 기본값(전부 활성)으로 남지 않게 한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
    // 1) 로딩 동안 버튼 잠금
    $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
    scwin.setRelAndChgRsnBtnShow();

    // 2) 달력 검사(규칙 37)·서버 현재일
    $c.date.checkCalendarFormat(edt_MktactEnforceDd, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_MktactEnforceChgDd, "yyyyMMdd");
    scwin.curDate = $c.date.getServerDateTime("yyyyMMdd");

    // 3) 파라미터 수신 — openPopup 의 3번째 인자 (원본 fn_GetPar arr 0~8)
    const param = $c.data.getParameter() ?? {};

    scwin.isurCd = param.isurCd ?? "";
    scwin.isurNm = param.isurNm ?? "";
    scwin.secugrpId = param.secugrpId ?? "";
    scwin.mktId = param.mktId ?? "";
    scwin.bzProcsNo = param.bzProcsNo ?? "";
    scwin.tpCd = param.admisuDesignBzTpCd ?? scwin.BZ_TP_RSN_CHG;
    scwin.isuCd = param.isuCd ?? "";
    scwin.selTp = param.selTp ?? "";
    scwin.orgBzProcsNo = param.admisuDesignBzProcsNo ?? "";

    // 4) 업무처리번호가 있으면 수정 조회, 없으면 신규 준비
    if ($c.util.isEmpty(scwin.bzProcsNo)) {
        await scwin.newOnload();
    } else {
        await scwin.search();
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @event
 * @name scwin.btn_rsn_add_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 사유추가 클릭. 관리종목지정사유 선택(ULDSTF92008)에서 고른 사유를 변경 후 사유 목록에 더한다. (원본 btn_rsn_add onclick — §6.3)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_rsn_add_onclick = async function (e) {
    try {
        await scwin.openRsnPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08034.btn_rsn_add_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_rsn_del_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 사유삭제 클릭. 변경 후 사유 목록에서 고른 행을 지운다. (원본 btn_rsn_del onclick — dts_Rsn_Af.DeleteRow(RowPosition))
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_rsn_del_onclick = async function (e) {
    try {
        const row = grd_RsnAf.getFocusedRowIndex();
        if (row < 0) return;

        dlt_rsnAf.removeRow(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08034.btn_rsn_del_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_Save_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 저장 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_Save_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08034.btn_Save_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_Update_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 수정 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_Update_onclick = async function (e) {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08034.btn_Update_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_Delete_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 삭제 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_Delete_onclick = async function (e) {
    try {
        await scwin.remove();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08034.btn_Delete_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_Dscl_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 안내문작성 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_Dscl_onclick = async function (e) {
    try {
        await scwin.writeDscl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08034.btn_Dscl_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_release_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 해제 클릭. 이 창을 닫으며 부모에 관리종목지정 해제(ULDSTF08033) 신규를 열어 달라고 돌려준다. (원본 fn_release — §6.6)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_release_onclick = async function (e) {
    try {
        await scwin.requestNext("ULDSTF08033", scwin.BZ_TP_RELEAS);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08034.btn_release_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_rsn_change_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 사유변경 클릭. 이 창을 닫으며 부모에 사유변경(ULDSTF08034) 신규를 열어 달라고 돌려준다. (원본 fn_rsnChange — §6.6)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_rsn_change_onclick = async function (e) {
    try {
        await scwin.requestNext("ULDSTF08034", scwin.BZ_TP_RSN_CHG);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08034.btn_rsn_change_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectOne
 * @author Inswave
 * @date 2026. 10. 30
 * @description 상세 묶음 조회(select-one). 사유변경 건 마스터·원 지정 건 마스터·종목·변경 전/후 사유를 한 번에 받아 화면 DataCollection 에 나눠 담는다.
 *
 * 원본은 같은 서비스를 DIV_IDX(MST·ISU_ITM·RSN_BF·RSN_AF)만 바꿔 다섯 번 불렀다(fn_search·fn_new_onload).
 * 명세 응답의 각 항목은 없으면 null 이 오므로 빈 값으로 바꿔 담는다(명세 「RESPONSE & 처리」).
 * 종목 목록은 발행기관의 종목 전체(등록 여부 selected)로 오므로 이 화면의 종목(isuCd) 한 건만 남긴다(§5.2).
 * @param {String} bzProcsNo 사유변경 건 업무처리번호 (신규면 빈 값)
 * @param {String} orgBzProcsNo 원 지정 건 업무처리번호
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
*/
scwin.selectOne = async function (bzProcsNo, orgBzProcsNo) {
    const sbmOptions = {
        id : "sbm_selectOne",
        method : "get",
        action : "/api/listing/lstproc/etn/adm-isu/select-one",
        isProcessMsg : false
    };

    const requestData = {
        bzProcsNo : bzProcsNo,          // 사유변경 건
        orgBzProcsNo : orgBzProcsNo,    // 원 지정 건
        isurCd : scwin.isurCd           // 종목 목록용 발행기관
    };

    // 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다.
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped || !result?.responseJSON?.success) return false;

    const body = result.responseJSON.body ?? {};

    dma_mst.setEmptyValue();
    if (body.mst) dma_mst.setJSON(body.mst);

    dma_mstBf.setEmptyValue();
    if (body.mstBf) dma_mstBf.setJSON(body.mstBf);

    dlt_isu.setJSON(scwin.pickIsuRows(body.isuList ?? []));
    dlt_rsnBf.setJSON(body.rsnBfList ?? []);
    dlt_rsnAf.setJSON(body.rsnAfList ?? []);

    return true;
};

/**
 * @method
 * @name scwin.selectRsnNew
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 — 변경 전 사유 초기값 조회(select-list-rsn-new). 해제 건 이후 최신 지정 건의 사유 목록이다. (원본 fn_search_rsn — §5.3)
 * @param
 * @returns
 * @hidden N
*/
scwin.selectRsnNew = async function () {
    const sbmOptions = {
        id : "sbm_selectRsnNew",
        method : "get",
        action : "/api/listing/lstproc/etn/adm-isu/select-list-rsn-new",
        target : "dlt_rsnBf=body",
        isProcessMsg : false
    };

    dlt_rsnBf.removeAll();
    await $c.sbm.executeDynamic(sbmOptions, { isuCd : scwin.isuCd });
};

/**
 * @method
 * @name scwin.checkDoubleInput
 * @author Inswave
 * @date 2026. 10. 30
 * @description 업무 중복입력 확인(check-double-input). 같은 종목·같은 시행일로 이미 입력된 건(자기 건 제외)이 있으면 안내하고 false.
 * (원본 fn_check_bz_doubleinput_etn — 업무구분 713 은 서버 고정, §5.4)
 * @param
 * @returns {Promise<Boolean>} 중복 없음(진행 가능) 여부
 * @hidden N
*/
scwin.checkDoubleInput = async function () {
    const sbmOptions = {
        id : "sbm_checkDoubleInput",
        method : "get",
        action : "/api/listing/lstproc/etn/adm-isu/check-double-input",
        target : "dma_checkDoubleInput=body",
        isProcessMsg : false
    };

    const requestData = {
        isuCd : scwin.isuCd,
        mktactEnforceDd : edt_MktactEnforceChgDd.getValue(),
        bzProcsNo : scwin.bzProcsNo
    };

    dma_checkDoubleInput.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped || !result?.responseJSON?.success) return false;

    const ddtm = dma_checkDoubleInput.get("disclsProcsDdtm");
    if (dma_checkDoubleInput.get("dupYn") === "Y" || !$c.util.isEmpty(ddtm)) {
        await $c.win.alert("[" + dma_checkDoubleInput.get("disclsProcsStatCd") + "]건으로 " + ddtm + "에 이미 입력되어있습니다.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.checkMstStatus
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 저장 전 종목 최신 처리상태 확인(select-one-status). 지정된 건이 없거나 최신 건이 해제면 사유변경을 저장할 수 없고,
 * 최신 건의 시행일이 입력한 변경일과 같거나 뒤면 예정된 업무가 있다고 안내한다. (원본 fn_getMstStatus_etn — §5.5)
 *
 * 원본 판정 함수(list_common_etn.js)는 저장소에 없어 상장 관리종목 판정(pcc getMstStatus)과 메시지 MSG-0020·0021 로 재구성했다.
 * 명세상 등록 API 가 같은 확인을 서버에서 하므로 이 확인은 저장 전 안내용이다(§10).
 * @param
 * @returns {Promise<Boolean>} 저장 가능 여부
 * @hidden N
*/
scwin.checkMstStatus = async function () {
    const sbmOptions = {
        id : "sbm_selectOneStatus",
        method : "get",
        action : "/api/listing/lstproc/etn/adm-isu/select-one-status",
        target : "dma_oneStatus=body",
        isProcessMsg : false
    };

    dma_oneStatus.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, { isuCd : scwin.isuCd });
    if (result?.skipped || !result?.responseJSON?.success) return false;

    // "신규 관리종목지정 업무를 저장 할 수 없습니다. 관리종목지정현황을 확인하세요." — 지정 건 없음 또는 이미 해제
    if ($c.util.isEmpty(dma_oneStatus.get("bzProcsNo")) || dma_oneStatus.get("admisuDesignBzTpCd") === scwin.BZ_TP_RELEAS) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0021", ""));
        return false;
    }

    // "입력한 일자보다, 예정된 관리종목지정업무가 있습니다."
    if (String(dma_oneStatus.get("mktactEnforceDd") ?? "") >= edt_MktactEnforceChgDd.getValue()) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0020", ""));
        edt_MktactEnforceChgDd.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 10. 30
 * @description 사유변경 등록(register-rsn-chg)·수정(modify-rsn-chg) 전송. 마스터와 변경 전/후 사유를 함께 보낸다. (원본 fn_save_trs — §5.6)
 *
 * 등록은 업무처리번호를 비워 보내 서버가 채번한다(명세 mstDto.bzProcsNo — 원본 fn_getNewBzProcNo 화면 채번을 없앴다).
 * 원본이 사유 행마다 넣던 변경전후구분·업무처리번호·지정해제구분·추가지정여부는 서버가 채운다(명세 bfRsnList·afRsnList 설명).
 * @param {String} trJob 처리구분 I: 저장, U: 수정
 * @returns {Promise<Object>} executeDynamic 결과
 * @hidden N
*/
scwin.saveTrs = async function (trJob) {
    const sbmOptions = {
        id : "sbm_saveTrs",
        method : "post",
        action : (trJob === "I") ? "/api/listing/lstproc/etn/adm-isu/register-rsn-chg"
                                 : "/api/listing/lstproc/etn/adm-isu/modify-rsn-chg",
        mediatype : "application/json",
        isProcessMsg : false
    };

    // 원 지정 건 번호 — 원본은 dts_Mst_Bf 의 ADMISU_DESIGN_BZ_PROCS_NO 를 옮겼다(명세상 사유변경 단건은 필수).
    const designBzProcsNo = dma_mstBf.get("admisuDesignBzProcsNo") || dma_mst.get("admisuDesignBzProcsNo") || scwin.orgBzProcsNo;

    const mstDto = {
        bzProcsNo : (trJob === "U") ? scwin.bzProcsNo : "",                     // 등록은 비워 서버 채번
        isuCd : scwin.isuCd,
        mktactEnforceDd : dma_mst.get("mktactEnforceDd"),                       // 사유변경일
        grndRegulNm : dma_mst.get("grndRegulNm"),                               // 근거규정
        admisuRsnContn : dma_mst.get("admisuRsnContn"),                         // 변경사유
        admisuDesignBzProcsNo : designBzProcsNo,
        remk : (trJob === "I") ? dma_mstBf.get("remk") : dma_mst.get("remk")    // 원본 fn_save: 원 지정 건 비고를 옮긴다
    };

    const toRsn = (row) => ({ admisuDesignRsnCd : row.admisuDesignRsnCd, admisuDesignRsnNm : row.admisuDesignRsnNm });

    const requestData = {
        mstDto : mstDto,
        bfRsnList : dlt_rsnBf.getAllJSON().map(toRsn),     // 변경 전 사유
        afRsnList : dlt_rsnAf.getAllJSON().map(toRsn),     // 변경 후 사유
        isuCdList : []                                      // 비우면 마스터 종목코드(단건 — 명세)
    };

    return await $c.sbm.executeDynamic(sbmOptions, requestData);
};

/**
 * @method
 * @name scwin.removeTrs
 * @author Inswave
 * @date 2026. 10. 30
 * @description 삭제(remove) 전송. 업무처리번호만 보낸다 — 승인된 시장안내공시 건은 서버가 막는다. (원본 fn_delete·fn_check_delete_discls — §5.7)
 * @param
 * @returns {Promise<Object>} executeDynamic 결과
 * @hidden N
*/
scwin.removeTrs = async function () {
    const sbmOptions = {
        id : "sbm_removeTrs",
        method : "post",
        action : "/api/listing/lstproc/etn/adm-isu/remove",
        mediatype : "application/json",
        isProcessMsg : false
    };

    return await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo : scwin.bzProcsNo });
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 10. 30
 * @description 수정 조회. 사유변경 건을 묶음 조회하고 버튼 상태를 정한다. (원본 fn_search + dts_Mst OnLoadCompleted 수정 분기 — §3)
 *
 * 부모가 원 지정 건 번호를 넘기지 않았으면 사유변경 건 마스터의 원 지정 번호로 한 번 더 조회한다(위 표가 비지 않게).
 * 버튼: 사유변경일이 오늘 이후면 수정 가능, 지났으면 error — 단 공시 전(공시여부 ≠ Y)이면 다시 수정 가능(원본 setButtonSetWithDate → setButtonSetWithDate2).
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    if (!await scwin.selectOne(scwin.bzProcsNo, scwin.orgBzProcsNo)) return;

    if ($c.util.isEmpty(scwin.orgBzProcsNo) && !$c.util.isEmpty(dma_mst.get("admisuDesignBzProcsNo"))) {
        scwin.orgBzProcsNo = dma_mst.get("admisuDesignBzProcsNo");
        if (!await scwin.selectOne(scwin.bzProcsNo, scwin.orgBzProcsNo)) return;
    }

    if ($c.util.isEmpty(scwin.isuCd)) scwin.isuCd = dma_mst.get("isuCd") || dlt_isu.getCellData(0, "isuCd");

    $c.stf.setButtonSetWithDate(edt_MktactEnforceChgDd, false, "grpBtnBox", scwin.BTN_MAP);
    $c.stf.setButtonSetWithDate2(dma_mst.get("dscYn"), "grpBtnBox", scwin.BTN_MAP);
    scwin.setRelAndChgRsnBtnShow();
};

/**
 * @method
 * @name scwin.newOnload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 준비. 원 지정 건과 그 종목을 조회하고, 변경 전 사유를 최신 지정 건에서 불러온 뒤 기본값을 넣는다. (원본 fn_new_onload + dts_Isu·dts_Mst OnLoadCompleted 신규 분기 — §3)
 *
 * 원본은 종목 조회가 끝난 뒤(OnLoadCompleted) 종목코드를 그 행 값으로 바꾸고 변경 전 사유를 조회했다 — 순서대로 await 한다.
 * 신규 마스터는 원본처럼 발행기관코드와 근거규정 기본값만 넣는다.
 * @param
 * @returns
 * @hidden N
*/
scwin.newOnload = async function () {
    if (!await scwin.selectOne("", scwin.orgBzProcsNo)) return;

    if (dlt_isu.getRowCount() > 0) scwin.isuCd = dlt_isu.getCellData(0, "isuCd");

    await scwin.selectRsnNew();

    dma_mst.setEmptyValue();
    dma_mst.set("isurCd", scwin.isurCd);
    dma_mst.set("grndRegulNm", scwin.DEFAULT_GRND_REGUL);
    dlt_rsnAf.removeAll();

    $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
    scwin.setRelAndChgRsnBtnShow();
};

/**
 * @method
 * @name scwin.pickIsuRows
 * @author Inswave
 * @date 2026. 10. 30
 * @description 묶음 조회의 종목 목록에서 이 화면의 종목만 고른다. 종목코드를 알면 그 종목, 모르면 등록된(selected T) 종목, 그것도 없으면 전부.
 *
 * 명세 select-one 의 isuList 는 발행기관의 종목 전체에 등록 여부(selected)를 붙여 준다 — 원본 dts_Isu 는 업무처리번호로 걸러 한 건이었다.
 * @param {Array} rows 응답 isuList
 * @returns {Array} 그리드에 둘 행
 * @hidden N
*/
scwin.pickIsuRows = function (rows) {
    if (!Array.isArray(rows)) return [];

    if (!$c.util.isEmpty(scwin.isuCd)) {
        const mine = rows.filter(row => row.isuCd === scwin.isuCd);
        if (mine.length > 0) return mine;
    }

    const selected = rows.filter(row => row.selected === "T");
    return (selected.length > 0) ? selected : rows;
};

/**
 * @method
 * @name scwin.setRelAndChgRsnBtnShow
 * @author Inswave
 * @date 2026. 10. 30
 * @description [해제]·[사유변경] 활성. 신규(저장 전)이거나 공시하지 않은 건(공시여부 N)이면 잠근다. (원본 fn_SetRelAndChgRsnBtnShow)
 * @param
 * @returns
 * @hidden N
*/
scwin.setRelAndChgRsnBtnShow = function () {
    const disabled = $c.util.isEmpty(scwin.bzProcsNo) || dma_mst.get("dscYn") === "N";

    btn_release.setDisabled(disabled);
    btn_rsn_change.setDisabled(disabled);
};

/**
 * @method
 * @name scwin.openRsnPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 관리종목지정사유 찾기(ULDSTF92008). 고른 사유가 변경 후 목록에 없으면 행을 더한다. 취소·닫기면 아무것도 하지 않는다.
 * (원본 fn_GetParRsnCd·fn_SetParRsnCd + fn_PopFindClssLstRsnCd(RSNCD_ADM_DESIGN) — §6.3)
 *
 * 중복 확인은 화면에서 0번 행부터 본다 — pcc isNewValueForDataSet 은 Gauce 식 1번 행부터 세어 첫 행을 보지 못한다(§8).
 * @param
 * @returns
 * @hidden N
*/
scwin.openRsnPopup = async function () {
    // AS-IS arr[0] "1"(유가), arr[1] "07"(관리종목), arr[5] "N"(기업인수목적회사 아님) → 92008 수신 키 mkt·rsn·spac
    const res = await $c.lc.popFindClssLstRsnCd(scwin.RSNCD_ADM_DESIGN, { mkt : "1", rsn : "07", spac : "N" });
    if (res?.isCloseButtonClick === true || $c.util.isEmpty(res?.code)) return;    // 취소·닫기

    const rowCount = dlt_rsnAf.getRowCount();
    for (let i = 0; i < rowCount; i++) {
        if (dlt_rsnAf.getCellData(i, "admisuDesignRsnCd") === res.code) {
            await $c.win.alert("이미 선택하신 사유가 있습니다.");
            return;
        }
    }

    const row = dlt_rsnAf.insertRow();
    dlt_rsnAf.setCellData(row, "admisuDesignRsnCd", res.code);
    dlt_rsnAf.setCellData(row, "admisuDesignRsnNm", res.name ?? "");
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 30
 * @description 저장·수정 전 입력값 검증. (원본 fn_CheckForm — §6.1)
 *
 * 순서는 원본과 같다: 변경일(익일 이후) → 변경 전 사유 → 변경 후 사유 → 변경사유·근거규정(필수·byte) → 업무 중복입력 확인.
 * 변경일은 원본 checkDdTm("DD", …, false) 와 같이 8자리·현재일 다음 날 이후만 받는다(pcc checkDdTm 은 Gauce 의 obj.text 를 읽어 쓰지 않는다).
 * 필수·byte 는 gcc 공통 검증 $c.validate.validateDataCollect 로 본다. 통신이 필요한 중복 확인은 맨 뒤에 둔다.
 * @param
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
*/
scwin.validate = async function () {
    const chgDd = String(edt_MktactEnforceChgDd.getValue() ?? "");

    if (chgDd.length !== 8) {
        await $c.win.alert("[변경일]을 정확히 입력하세요.");
        edt_MktactEnforceChgDd.focus();
        return false;
    }
    if (scwin.curDate >= chgDd) {
        await $c.win.alert("[변경일]을 익일 이후로 입력하세요.");
        edt_MktactEnforceChgDd.focus();
        return false;
    }

    if (dlt_rsnBf.getRowCount() === 0) {
        await $c.win.alert("[변경전 지정사유]가 없어 처리할 수 없습니다.");
        return false;
    }
    if (dlt_rsnAf.getRowCount() === 0) {
        await $c.win.alert("[변경후 지정사유]를 선택하세요.");
        btn_rsn_add.focus();
        return false;
    }

    const options = {
        validateType : "alert",     // alert|mark|all
        checkType : "single",       // single|multi
        fields : {
            txa_ChgRsnContn : { required : true, maxLengthB : 2000, name : "변경사유" },
            txb_ChgAdmisuDesignGrndRegulNm : { required : true, maxLengthB : 200, name : "근거규정" }
        }
    };
    if (!await $c.validate.validateDataCollect(panel_2, options)) return false;

    return await scwin.checkDoubleInput();
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 저장. 검증 → 최신 처리상태 확인 → 사용자 확인 → 등록. (원본 fn_save — §6.2)
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
    scwin.trJob = "I";

    if (!await scwin.validate()) return;
    if (!await scwin.checkMstStatus()) return;

    // "[저장] 처리를 하시겠습니까?" 확인 — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.afterSave(scwin.trJob, await scwin.saveTrs(scwin.trJob));
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 30
 * @description 수정. 검증 → 사용자 확인 → 수정. (원본 fn_update — §6.2)
 * @param
 * @returns
 * @hidden N
*/
scwin.update = async function () {
    scwin.trJob = "U";

    if (!await scwin.validate()) return;

    // "[수정] 처리를 하시겠습니까?" 확인 — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.afterSave(scwin.trJob, await scwin.saveTrs(scwin.trJob));
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 10. 30
 * @description 삭제. 사용자 확인 → 삭제. 성공하면 { isSaved : true } 로 창을 닫는다. (원본 fn_delete — §6.2)
 *
 * 원본의 승인 공시 확인(fn_check_delete_discls)은 명세상 remove 가 서버에서 한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.remove = async function () {
    scwin.trJob = "D";

    // "[삭제] 처리를 하시겠습니까?" 확인 — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.afterSave(scwin.trJob, await scwin.removeTrs());
};

/**
 * @method
 * @name scwin.afterSave
 * @author Inswave
 * @date 2026. 10. 30
 * @description 처리 결과 안내와 뒤처리. (원본 trs OnSuccess·OnFail — §5.8)
 *
 *  - 실패: 실패를 안내하고 [해제]·[사유변경] 상태만 다시 맞춘다.
 *  - 삭제 성공: { isSaved : true } 로 창을 닫는다 — 부모가 목록을 다시 조회한다.
 *  - 저장·수정 성공: 등록이면 응답의 업무처리번호를 받아 수정 상태로 바꾸고, 그 번호로 다시 조회한다.
 * 원본의 부모 직접 호출(fn_parentRefresh → 부모 fn_parentRefresh/fn_search)은 반환 규약으로 대신한다(공통 계약서 §3.2).
 * @param {String} trJob 처리구분 I: 저장, U: 수정, D: 삭제
 * @param {Object} result executeDynamic 결과
 * @returns
 * @hidden N
*/
scwin.afterSave = async function (trJob, result) {
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    const jobNm = { I : "저장", U : "수정", D : "삭제" }[trJob];

    if (result?.responseJSON?.success !== true) {
        await $c.win.alert($c.data.getMessage("com_complete_0151", jobNm));
        scwin.setRelAndChgRsnBtnShow();
        return;
    }

    // "com_complete_0096": "$[0] 되었습니다."
    await $c.win.alert($c.data.getMessage("com_complete_0096", jobNm));

    if (trJob === "D") {
        await $c.win.closePopup({ isSaved : true });
        return;
    }

    scwin.isSaved = true;

    if (trJob === "I") {
        const newNo = scwin.getBzProcsNoOf(result.responseJSON.body);

        // TODO: 등록 응답 모양이 명세에 없다(target dlt_resultSave) — 번호를 못 받으면 다시 저장하지 못하게 잠근다 (§10)
        if ($c.util.isEmpty(newNo)) {
            $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
            return;
        }
        scwin.bzProcsNo = newNo;
    }

    await scwin.search();
};

/**
 * @method
 * @name scwin.getBzProcsNoOf
 * @author Inswave
 * @date 2026. 10. 30
 * @description 등록 응답 body 에서 업무처리번호를 꺼낸다 — 문자열, { bzProcsNo }, [{ bzProcsNo }] 어느 모양이든 받는다(명세 응답 미정의, 선례 09312·05105).
 * @param {*} body 응답 body
 * @returns {String} 업무처리번호 (없으면 빈 값)
 * @hidden N
*/
scwin.getBzProcsNoOf = function (body) {
    if (typeof body === "string") return body;
    if (Array.isArray(body)) return String(body[0]?.bzProcsNo ?? "");
    return String(body?.bzProcsNo ?? "");
};

/**
 * @method
 * @name scwin.requestNext
 * @author Inswave
 * @date 2026. 10. 30
 * @description [해제]·[사유변경] — 이 창을 닫으며 다음에 열 화면과 그 data 를 부모에 돌려준다. (원본 fn_release·fn_rsnChange + fn_GetParRelease·fn_GetParRsnChange — §6.6)
 *
 * 원본은 형제 팝업을 연 뒤 자기 창을 닫았다. 팝업 안에서 팝업을 열고 닫으면 자식 창의 수명이 끊기므로
 * 부모 08031 이 재조회 뒤 next 의 화면을 연다(공통 계약서 §3.2). selTp "0" 은 형제 팝업에서 왔다는 원본 표시다.
 * @param {String} id 다음 화면 ID (ULDSTF08033 해제 / ULDSTF08034 사유변경)
 * @param {String} tpCd 관리종목지정업무구분코드 (4: 해제 / 1: 사유변경)
 * @returns
 * @hidden N
*/
scwin.requestNext = async function (id, tpCd) {
    const data = {
        isurCd : scwin.isurCd,                      // arr[0] 발행기관코드
        isurNm : scwin.isurNm,                      // arr[1] 발행기관명
        secugrpId : scwin.secugrpId,                // arr[2] 증권그룹ID
        mktId : scwin.mktId,                        // arr[3] 시장구분코드
        bzProcsNo : "",                             // arr[4] 신규라 업무처리번호 없음
        admisuDesignBzTpCd : tpCd,                  // arr[5] 4 해제 / 1 사유변경
        isuCd : scwin.isuCd,                        // arr[6] 종목코드
        selTp : "0",                                // arr[7] 형제 팝업에서 옴
        admisuDesignBzProcsNo : scwin.orgBzProcsNo  // arr[8] 원 지정 건 업무처리번호
    };

    await $c.win.closePopup({ isSaved : scwin.isSaved, next : { id : id, data : data } });
};

/**
 * @method
 * @name scwin.getDsclData
 * @author Inswave
 * @date 2026. 10. 30
 * @description 공시안내문작성(ULDSTF92024)에 넘길 값. 원본 fn_dscl 이 fn_GetPar 로 채우던 arr 과 데이터셋 4개(마스터·종목·변경 전/후 사유)다. (§6.5)
 *
 * 마스터에는 원본처럼 대상명(tgtNm — 원본 TGT_NM = 발행기관명)과 발행회사명(comNm — 종목 행의 값)을 더한다.
 * 원본 arr 는 [4] 를 비우고 [5] 공시제목(종목명)을 넣어 길이가 6 이다.
 * @param
 * @returns {Object} 넘길 data
 * @hidden N
*/
scwin.getDsclData = function () {
    const isuRow = Math.max(grd_Isu.getFocusedRowIndex(), 0);
    const isu = dlt_isu.getRowCount() > 0 ? dlt_isu.getRowJSON(isuRow) : {};

    return {
        formCd : scwin.DSCL_FORM_CD,                // arr[0] "68346"
        bzProcsNo : scwin.bzProcsNo,                // arr[1] 업무처리번호
        isurCd : scwin.isurCd,                      // arr[2] 발행기관코드
        mktId : scwin.DSCL_MKT_ID,                  // arr[3] "1"
        msg : "",                                   // arr[4] (원본 비움)
        title : isu.isuNm ?? "",                    // arr[5] 종목명
        isu : dlt_isu.getAllJSON(),                 // CopyDataSet(dts_Isu)
        mst : [{ ...dma_mst.getJSON(), tgtNm : scwin.isurNm, comNm : isu.comNm ?? "" }],   // CopyDataSet(dts_Mst) + TGT_NM·COM_NM
        rsnBf : dlt_rsnBf.getAllJSON(),             // CopyDataSet(dts_Rsn)
        rsnAf : dlt_rsnAf.getAllJSON()              // CopyDataSet(dts_Rsn_Af)
    };
};

/**
 * @method
 * @name scwin.writeDscl
 * @author Inswave
 * @date 2026. 10. 30
 * @description 공시안내문작성. 공시안내문작성 팝업(ULDSTF92024)을 data 로 넘겨 열고 닫힐 때까지 기다린다. 원본처럼 닫힌 뒤 다시 조회하지 않는다. (원본 fn_dscl — §6.5)
 * @param
 * @returns
 * @hidden N
*/
scwin.writeDscl = async function () {
    const options = {
        id : "ULDSTF92024",
        popupName : "공시안내문작성",
        width : 745,
        height : 820,
        type : "pageFramePopup"
    };

    // TODO: 경로는 conversion-front 선례(/ui/listingcommon/), 92024 는 아직 getPar 계약이라 수신부 변경 필요 (§10)
    await $c.win.openPopup("/ui/listingcommon/ULDSTF92024.xml", options, scwin.getDsclData());
};

/**
 * @method
 * @name scwin.getPar
 * @author Inswave
 * @date 2026. 10. 30
 * @description [호환용 · 임시] 공시안내문작성(ULDSTF92024) 전환본은 아직 부모의 scwin.getPar 를 이름으로 불러 값을 받는다.
 * 92024 가 $c.data.getParameter() 수신으로 바뀌면 이 함수를 지운다. (§6.5, §10, 가이드 §6.5 예외)
 * @param {Array} arr 92024 가 넘기는 빈 배열 — [0] 서식코드 [1] 업무처리번호 [2] 발행기관코드 [3] 시장구분 [4] 메시지 [5] 공시제목 을 채운다
 * @param {Object} dltIsu 92024 의 종목 dataList
 * @param {Object} dltMst 92024 의 마스터 dataList
 * @param {Object} dlt2 92024 의 원천 자료 2 (변경 전 사유)
 * @param {Object} dlt3 92024 의 원천 자료 3 (변경 후 사유)
 * @returns {Number} arr 길이
 * @hidden N
*/
scwin.getPar = function (arr, dltIsu, dltMst, dlt2, dlt3) {
    const data = scwin.getDsclData();

    arr[0] = data.formCd;
    arr[1] = data.bzProcsNo;
    arr[2] = data.isurCd;
    arr[3] = data.mktId;
    arr[4] = data.msg;
    arr[5] = data.title;

    scwin.fillDataList(dltIsu, data.isu);
    scwin.fillDataList(dltMst, data.mst);
    scwin.fillDataList(dlt2, data.rsnBf);
    scwin.fillDataList(dlt3, data.rsnAf);

    return arr.length;
};

/**
 * @method
 * @name scwin.fillDataList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 컬럼 정의가 비어 있는 92024 의 원천 dataList 에 행 키를 컬럼으로 더하고 행을 채운다. (원본 CopyDataSet 의 헤더 복사 — §6.5)
 * @param {Object} dataList 채울 dataList
 * @param {Array} rows 행 배열
 * @returns
 * @hidden N
*/
scwin.fillDataList = function (dataList, rows) {
    if (!dataList) return;

    Object.keys(rows[0] ?? {}).forEach(key => {
        if (dataList.getColumnIndex(key) < 0) dataList.insertColumn(key);
    });
    dataList.setJSON(rows);
};
